 * replaced, and only the people not already mentioned before the edit are
 * announced as newly mentioned.
 */
export async function updateComment(
  actor: Actor,
  input: UpdateCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const comment = requireFound(
    await commentRepo.findCommentById(input.orgId, input.commentId),
    "Comment",
    input.commentId,
  );
  assertCan(actor, "comment:update", commentResource(comment));
  assertNotArchived("Comment", comment.id, comment);

  if (comment.authorId === actor.userId && isPastEditWindow(comment)) {
    throw new Error("The edit window for this comment has closed");
  }

  const mentionedUserIds = await resolveMentionedUsers(
    input.orgId,
    input.body,
    comment.authorId,
  );
  const alreadyMentioned = new Set(comment.mentionedUserIds);

  const updated = await commentRepo.updateComment(input, mentionedUserIds);

  await emit("comment.updated", {
    ...actorEnvelope(actor),
    commentId: updated.id,
    issueId: updated.issueId,
    mentionedUserIds,
    newlyMentionedUserIds: mentionedUserIds.filter(
      (userId) => !alreadyMentioned.has(userId),
    ),
  });

  return updated;
}

