    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "zebrawording",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.id)).toEqual([comment.id]);

    const dropped = await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "no one now",
    });
    expect(dropped.mentionedUserIds).toEqual([]);
  });
});

describe("posting limit", () => {
  it("charges a burst to the member who posted it", async () => {
    const issue = await newIssue();
    let refused = false;
    for (let i = 0; i < 400 && !refused; i += 1) {
      try {
        await post(tenant.actors.member, issue, `flood ${i}`);
      } catch (error) {
        refused = /rate limit/i.test(String(error));
        if (!refused) throw error;
      }
    }
    expect(refused).toBe(true);

    await expect(post(tenant.actors.admin, issue, "still fine")).resolves.toMatchObject({
      body: "still fine",
    });
  });
});

