/**
 * Mentions, alerts, threads, edits and posting limits for issue discussions.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { resetRateLimits } from "@/lib/rate-limit";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";
import type { NotificationKind } from "@/types/notification";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let detach: Unsubscribe;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("discussion", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  resetRateLimits();
  vi.useRealTimers();
});

async function newIssue(assigneeId: UserId | null = null): Promise<Issue> {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Discussion", assigneeId }),
  );
}

function post(actor: Actor, issue: Issue, body: string, parentId: CommentId | null = null) {
  return commentService.createComment(actor, {
    orgId: tenant.org.id,
    issueId: issue.id,
    body,
    parentId,
    mentionedUserIds: [],
  });
}

async function alertsFor(userId: UserId, kind: NotificationKind) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    kind: [kind],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("mentions", () => {
  it("reaches viewers, and every member sharing a handle", async () => {
    const issue = await newIssue();
    const twin = await userRepo.insertUser({
      email: "Admin@elsewhere.test",
      name: "Another admin",
      passwordHash: "seed",
    });
    await memberRepo.insertMember(tenant.org.id, twin.id, "member", null);

    const comment = await post(tenant.actors.member, issue, "ping @viewer and @ADMIN");

    expect([...comment.mentionedUserIds].sort()).toEqual(
      [tenant.userIds.viewer, tenant.userIds.admin, twin.id].sort(),
    );
  });

  it("ignores the author's own handle and members who are no longer active", async () => {
    const issue = await newIssue();
    const gone = await userRepo.insertUser({
      email: "gone@discussion.test",
      name: "Gone",
      passwordHash: "seed",
    });
    const membership = await memberRepo.insertMember(tenant.org.id, gone.id, "member", null);
    await memberRepo.archiveMember(tenant.org.id, membership.id);

    const comment = await post(tenant.actors.member, issue, "@member @gone @owner");

    expect(comment.mentionedUserIds).toEqual([tenant.userIds.owner]);
  });

  it("still finds the longest-standing members in a large workspace", async () => {
    const big = await createTenant("big-workspace", "growth");
    for (let i = 0; i < 130; i += 1) {
      const user = await userRepo.insertUser({
        email: `person${i}@big-workspace.test`,
        name: `Person ${i}`,
        passwordHash: "seed",
      });
      await memberRepo.insertMember(big.org.id, user.id, "member", null);
    }
    const issue = await issueService.createIssue(
      big.actors.member,
      issueInput(big.org.id, big.project.id, { title: "Big" }),
    );

    const comment = await commentService.createComment(big.actors.member, {
      orgId: big.org.id,
      issueId: issue.id,
      body: "@owner and @person0",
      parentId: null,
      mentionedUserIds: [],
    });

    expect(comment.mentionedUserIds).toHaveLength(2);
    expect(comment.mentionedUserIds).toContain(big.userIds.owner);
  });
});

describe("alerts", () => {
  it("gives a mentioned assignee one mention alert and no comment alert", async () => {
    const issue = await newIssue(tenant.userIds.admin);
    await post(tenant.actors.member, issue, "over to you @admin");

    const mentions = (await alertsFor(tenant.userIds.admin, "comment_mention")).filter((n) =>
      n.href.includes(issue.id),
    );
    const comments = (await alertsFor(tenant.userIds.admin, "comment_created")).filter((n) =>
      n.href.includes(issue.id),
    );
    expect(mentions).toHaveLength(1);
    expect(comments).toHaveLength(0);
  });

  it("tells the author of the answered comment about a reply, not the replier", async () => {
    const issue = await newIssue();
    const top = await post(tenant.actors.admin, issue, "first");
    await post(tenant.actors.owner, issue, "second", top.id);

    const forAdmin = (await alertsFor(tenant.userIds.admin, "comment_created")).filter((n) =>
      n.href.includes(issue.id),
    );
    const forOwner = (await alertsFor(tenant.userIds.owner, "comment_created")).filter((n) =>
      n.href.includes(issue.id),
    );
    expect(forAdmin.length).toBeGreaterThanOrEqual(1);
    // The owner replied, and also wrote nothing else here: no alert for them.
    expect(forOwner.filter((n) => n.actorId === tenant.userIds.owner)).toHaveLength(0);
  });
});

describe("threads", () => {
  it("lists every descendant under its top-level comment and keeps deleted ones", async () => {
    const issue = await newIssue();
    const top = await post(tenant.actors.member, issue, "root");
    const reply = await post(tenant.actors.admin, issue, "reply", top.id);
    const nested = await post(tenant.actors.owner, issue, "nested", reply.id);
    const deeper = await post(tenant.actors.member, issue, "deeper", nested.id);
    const other = await post(tenant.actors.member, issue, "other root");

    await commentService.deleteComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      commentId: reply.id,
    });

    const thread = await commentService.getThread(tenant.actors.member, tenant.org.id, issue.id);
    expect(thread.map((node) => node.comment.id)).toEqual([top.id, other.id]);
    expect(thread[0]?.replies.map((r) => r.id)).toEqual([reply.id, nested.id, deeper.id]);
    expect(thread[0]?.replies[0]).toMatchObject({ body: "" });
    expect(thread[0]?.replies[0]?.archivedAt).not.toBeNull();

    expect(await commentRepo.countComments(tenant.org.id, issue.id)).toBe(4);
  });
});

